export interface ITimeLocale {
    second: string;
    seconds: string;
    minute: string;
    minutes: string;
    hour: string;
    hours: string;
}

export function formatTime(timeInSeconds: number, locale: ITimeLocale, hasSeconds?: boolean, spacingCharacter: string = ' '): string {
    timeInSeconds = Number(timeInSeconds);
    const hours = Math.floor(timeInSeconds / 3600);
    const minutes = Math.floor(timeInSeconds % 3600 / 60);
    const seconds = Math.floor(timeInSeconds % 3600 % 60);

    const hDisplay = hours > 0 ? hours + (hours === 1 ? `${spacingCharacter}${locale.hour}` : `${spacingCharacter}${locale.hours}`) : '';
    const mDisplay = minutes > 0 ? minutes + (minutes === 1 ? `${spacingCharacter}${locale.minute}` : `${spacingCharacter}${locale.minutes}`) : '';
    const sDisplay = seconds > 0 ? seconds + (seconds === 1 ? `${spacingCharacter}${locale.second}` : `${spacingCharacter}${locale.seconds}`) : '';

    let timeDisplay = hDisplay;
    timeDisplay += (timeDisplay && mDisplay ? ` ${mDisplay}` : mDisplay);

    if (hasSeconds) {
        timeDisplay += (timeDisplay && sDisplay ? ` ${sDisplay}` : sDisplay);
    }

    return timeDisplay;
}
